func characterFrequencies(_ text: String) -> [Character: Int] {
    var counts: [Character: Int] = [:]
    for character in text {
        counts[character, default: 0] += 1
    }
    return counts
}

let result = characterFrequencies("swift")
print(result["s"] ?? 0)
print(result["w"] ?? 0)

func findTwoSum(_ numbers: [Int], target: Int) -> (Int, Int)? {
    var seen = Set<Int>()
    for number in numbers {
        let complement = target - number
        if seen.contains(complement) {
            return (complement, number)
        }
        seen.insert(number)
    }
    return nil
}

if let pair = findTwoSum([2, 7, 11, 15], target: 9) {
    print("\(pair.0) + \(pair.1) = 9")
}

func firstUniqueCharacter(_ text: String) -> Character? {
    var counts: [Character: Int] = [:]
    for character in text {
        counts[character, default: 0] += 1
    }
    for character in text {
        if counts[character] == 1 {
            return character
        }
    }
    return nil
}

let char = firstUniqueCharacter("swiss")
print(char ?? "none")
